<!--
 * Agent 定义管理（列表页）
 *
 * 视图模式：卡片视图（默认）/ 表格视图 可切换。
 *  - 卡片视图：YdCardGrid + YdEntityCard，承载信息密度高的 Agent 展示；
 *  - 表格视图：VxeTable，保持原有兼容视图。
 *
 * @path apps/agent-web/src/views/agent/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * Agent 定义管理（列表页）
 * <p>消费后端 AgentDefinitionController 契约（auto-generated by bash/gen-contract.py）：
 * 数据源使用 list()（无分页端点），支持编辑（弹窗回填）与删除（二次确认）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';
import { YdCardGrid, YdEmptyState, YdEntityCard } from '@ydsz-core/shadcn-ui';
import { Page, useYDSZModal } from '@ydsz/common-ui';
import { h, ref } from 'vue';
// TODO: ElDropdown/ElDropdownItem/ElDropdownMenu 暂无 shadcn 对应,保留 element-plus SKIP
import { ElDropdown, ElDropdownItem, ElDropdownMenu } from 'element-plus';
import { Button } from '@ydsz-core/ui-kit/shadcn-ui';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteApi, list } from '#/api/agentDefinition';
import type { AgentDefinitionVO } from '#/api/models';
import AgentForm from './agent-form.vue';

defineOptions({ name: 'AgentManagement' });

type ViewMode = 'card' | 'table';
const viewMode = ref<ViewMode>('card');
const agentList = ref<AgentDefinitionVO[]>([]);
const loading = ref<boolean>(false);

const gridOptions: VxeTableGridOptions<AgentDefinitionVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'agentCode', title: 'Agent编码', width: 140 },
    { field: 'agentName', title: 'Agent名称', width: 160 },
    { field: 'agentType', title: '类型', width: 120 },
    { field: 'description', title: '描述', width: 200, showOverflow: true },
    { field: 'temperature', title: '温度', width: 80 },
    { field: 'maxTokens', title: 'MaxTokens', width: 110 },
    { field: 'toolNames', title: '工具列表', width: 160, showOverflow: true },
    { field: 'createdAt', title: '创建时间', width: 160 },
    { field: 'updatedAt', title: '更新时间', width: 160 },
    { field: 'createdBy', title: '创建人', width: 100 },
    { field: 'updatedBy', title: '更新人', width: 100 },
    {
      field: 'action', title: '操作', width: 140, fixed: 'right',
      slots: { default: ({ row }) => h('div', { class: 'flex gap-1' }, [
        h(Button, { size: 'sm', variant: 'link', onClick: () => handleEdit(row) }, () => '编辑'),
        h(Button, { size: 'sm', variant: 'link', onClick: () => handleDelete(row) }, () => '删除'),
      ]) },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await list();
        return { items: items ?? [], total: items?.length ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: { enabled: true, items: [
    { field: 'agentCode', title: 'Agent编码', itemRender: { name: 'Input', props: { placeholder: 'Agent编码' } } },
    { field: 'agentName', title: 'Agent名称', itemRender: { name: 'Input', props: { placeholder: 'Agent名称' } } },
  ] },
};
const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [AgentFormModal, agentFormApi] = useYDSZModal({ connectedComponent: AgentForm });

/** 加载 Agent 列表数据 */
async function loadAgentList(): Promise<void> {
  loading.value = true;
  try {
    agentList.value = (await list()) ?? [];
  } catch {
    agentList.value = [];
  } finally {
    loading.value = false;
  }
}

/** 视图模式切换 */
function handleViewModeChange(mode: ViewMode): void {
  if (mode === 'card' && agentList.value.length === 0 && !loading.value) {
    void loadAgentList();
  }
  viewMode.value = mode;
}

/** 卡片视图编辑 */
function handleCardEdit(row: AgentDefinitionVO): void {
  handleEdit(row);
}

/** 卡片视图删除 */
function handleCardDelete(row: AgentDefinitionVO): void {
  handleDelete(row);
}

/** 刷新列表（兼容两个视图） */
async function handleRefresh(): Promise<void> {
  if (viewMode.value === 'table') {
    gridApi.query();
  } else {
    await loadAgentList();
  }
}

/** 打开新增弹窗 */
function handleAdd(): void { agentFormApi.open(); }

/** 打开编辑弹窗，回填行数据 */
function handleEdit(row: AgentDefinitionVO): void { agentFormApi.setData({ record: row }); agentFormApi.open(); }

/** 删除定义，二次确认后调用 deleteApi({ id }) */
async function handleDelete(row: AgentDefinitionVO): Promise<void> {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(`确定删除「${row.agentName ?? row.agentCode ?? ''}」吗？`, { title: '删除确认', type: 'warning' });
  } catch {
    // 用户主动取消删除操作
    return;
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await deleteApi({ id: row.id ?? '' });
    showToast.success('删除成功');
    await handleRefresh();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}

/** 初始加载卡片数据（默认视图为卡片） */
void loadAgentList();
</script>

<template>
  <Page auto-content-height>
    <!-- 视图切换 + 工具栏 -->
    <div class="mb-4 flex items-center justify-between">
      <div class="flex items-center gap-1 rounded-lg border border-border-subtle bg-accent/50 p-1">
        <button
          class="rounded-md px-2.5 py-1 text-xs transition-colors"
          :class="viewMode === 'card' ? 'bg-surface-2 text-text-primary shadow-sm' : 'text-text-secondary hover:text-text-primary'"
          type="button"
          @click="handleViewModeChange('card')"
        >
          <svg
            class="mb-0.5 me-1 inline"
            fill="none"
            height="14"
            stroke="currentColor"
            viewBox="0 0 24 24"
            width="14"
          >
            <rect
              height="9"
              rx="1.5"
              width="9"
              x="2.5"
              y="2.5"
            />
            <rect
              height="9"
              rx="1.5"
              width="9"
              x="12.5"
              y="2.5"
            />
            <rect
              height="9"
              rx="1.5"
              width="9"
              x="2.5"
              y="12.5"
            />
            <rect
              height="9"
              rx="1.5"
              width="9"
              x="12.5"
              y="12.5"
            />
          </svg>
          卡片
        </button>
        <button
          class="rounded-md px-2.5 py-1 text-xs transition-colors"
          :class="viewMode === 'table' ? 'bg-surface-2 text-text-primary shadow-sm' : 'text-text-secondary hover:text-text-primary'"
          type="button"
          @click="handleViewModeChange('table')"
        >
          <svg
            class="mb-0.5 me-1 inline"
            fill="none"
            height="14"
            stroke="currentColor"
            stroke-width="1.8"
            viewBox="0 0 24 24"
            width="14"
          >
            <line
              x1="3"
              x2="21"
              y1="6.5"
              y2="6.5"
            />
            <line
              x1="3"
              x2="21"
              y1="12"
              y2="12"
            />
            <line
              x1="3"
              x2="21"
              y1="17.5"
              y2="17.5"
            />
            <line
              x1="8.5"
              x2="8.5"
              y1="3"
              y2="21"
            />
          </svg>
          表格
        </button>
      </div>
      <Button @click="handleAdd">新增</Button>
    </div>

    <!-- 表格视图 -->
    <Grid
      v-if="viewMode === 'table'"
      table-title="Agent定义管理"
    />

    <!-- 卡片视图 -->
    <div
      v-else
      class="min-h-[400px]"
    >
      <YdCardGrid
        :is-empty="agentList.length === 0 && !loading"
        :is-loading="loading"
      >
        <template #empty>
          <YdEmptyState
            description="创建 Agent 后可在应用中心调用"
            preset="created"
            action-text="创建 Agent"
            title="暂无 Agent"
            @action="handleAdd"
          />
        </template>
        <YdEntityCard
          v-for="item in agentList"
          :key="item.id"
          :avatar-text="item.agentName"
          :avatar-variant="item.agentType === 'CHAT' ? 'primary' : (item.agentType === 'WORKFLOW' ? 'purple' : 'blue')"
          :code="item.agentCode"
          :description="item.description"
          class="transition-transform hover:-translate-y-0.5"
          @click="handleCardEdit(item)"
        >
          <template #meta>
            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">
              <div class="rounded-md bg-accent/60 px-2 py-1.5">
                <span class="text-text-tertiary">模型温度</span>
                <div class="mt-0.5 font-medium text-text-secondary">{{ item.temperature ?? '-' }}</div>
              </div>
              <div class="rounded-md bg-accent/60 px-2 py-1.5">
                <span class="text-text-tertiary">MaxTokens</span>
                <div class="mt-0.5 font-medium text-text-secondary">{{ item.maxTokens ?? '-' }}</div>
              </div>
            </div>
          </template>

          <template #footer-left>
            <span>{{ item.updatedAt ?? item.createdAt ?? '' }}</span>
          </template>

          <template #actions>
            <!-- TODO: ElDropdown trigger 暂保留 element-plus,Button 仅作视觉替换 SKIP -->
            <ElDropdown trigger="click" @command="(cmd: string) => cmd === 'edit' ? handleCardEdit(item) : handleCardDelete(item)">
              <Button
                size="sm"
                variant="ghost"
                @click.stop
              >
                <svg
                  class="me-1"
                  fill="none"
                  height="14"
                  stroke="currentColor"
                  stroke-linecap="round"
                  stroke-width="2"
                  viewBox="0 0 24 24"
                  width="14"
                >
                  <circle
                    cx="12"
                    cy="5"
                    r="1"
                  />
                  <circle
                    cx="12"
                    cy="12"
                    r="1"
                  />
                  <circle
                    cx="12"
                    cy="19"
                    r="1"
                  />
                </svg>
              </Button>
              <template #dropdown>
                <ElDropdownMenu>
                  <ElDropdownItem command="edit">
                    编辑信息
                  </ElDropdownItem>
                  <ElDropdownItem
                    command="delete"
                    divided
                  >
                    <span class="text-destructive">删除定义</span>
                  </ElDropdownItem>
                </ElDropdownMenu>
              </template>
            </ElDropdown>
          </template>
        </YdEntityCard>
      </YdCardGrid>
    </div>

    <AgentFormModal @success="handleRefresh()" />
  </Page>
</template>
